// The automation watches a single fiscal host: Open Source Europe,
// whose host slug on Open Collective is 'europe'.
return [
  { json: { host_slug: 'europe', org: 'OSE' } },
];

// Flattens the per-host GraphQL responses into one item per pending
// application, shaped exactly like an ose_applications row.
// ONLY_SLUGS (a safety control — see automation/.env.example) restricts
// processing to named collectives; empty means all.
const ORG_BY_HOST = { 'europe': 'OSE' };
const only = ($env.ONLY_SLUGS || '').split(',').map((s) => s.trim()).filter(Boolean);
const out = [];
for (const item of $input.all()) {
  const host = item.json.data && item.json.data.host;
  if (!host) {
    throw new Error('intake: unexpected GraphQL response: ' + JSON.stringify(item.json.errors || item.json).slice(0, 500));
  }
  for (const node of host.hostApplications.nodes) {
    const account = node.account || {};
    if (!account.slug) continue;
    if (only.length && !only.includes(account.slug)) continue;
    const links = account.socialLinks || [];
    const repoLink = links.find((l) => ['GITHUB', 'GITLAB', 'GIT_REPOSITORY'].includes(l.type));
    const siteLink = links.find((l) => l.type === 'WEBSITE');
    const adminEmails = ((account.members || {}).nodes || [])
      .map((m) => (m.account || {}).email)
      .filter(Boolean);
    const custom = node.customData || {};
    out.push({ json: {
      slug: account.slug,
      org: ORG_BY_HOST[host.slug] || host.slug,
      host_slug: host.slug,
      collective_name: account.name || account.slug,
      collective_url: 'https://opencollective.com/' + account.slug,
      description: account.description || '',
      long_description: account.longDescription || '',
      repository_url: (repoLink || {}).url || '',
      website_url: (siteLink || {}).url || '',
      application_message: node.message || '',
      applicant_email: custom.email || custom.contactEmail || adminEmails[0] || '',
      applied_at: node.createdAt,
    }});
  }
}
return out;

// Pairs each status response with its state row (the HTTP node emits one
// response per input row, in order) and keeps only rows whose application
// was decided on Open Collective.
const rows = $('Still open?').all();
const out = [];
$input.all().forEach((item, i) => {
  const row = rows[i].json;
  const account = item.json.data && item.json.data.account;
  if (!account) return; // collective gone or renamed — leave the row for a human
  const requests = (account.hostApplicationRequests || {}).nodes || [];
  const forThisHost = requests.find((r) => r.host && r.host.slug === row.host_slug);
  if (!forThisHost) return;
  if (forThisHost.status === 'APPROVED' || forThisHost.status === 'REJECTED') {
    out.push({ json: {
      slug: row.slug,
      org: row.org,
      collective_name: row.collective_name,
      applicant_email: row.contact_email || row.applicant_email || '',
      decision: forThisHost.status.toLowerCase(),
    }, pairedItem: { item: i } });
  }
});
return out;
